#include "navcore/road_event.hpp"
#include "navcore/route_monitor.hpp"
#include <iostream>
int main(){try{navcore::RoadGraph g;for(auto id:{"A","B","C","D"})g.add_node({id,0,0});g.add_edge({"A","B",10,50,1,"x",true});g.add_edge({"B","D",10,50,1,"x",true});g.add_edge({"A","C",15,50,2,"x",true});g.add_edge({"C","D",15,50,2,"x",true});auto old=navcore::route(g,"A","D");navcore::RoadEventOverlay e;e.close("B->D");navcore::RouteOptions o;e.apply(o);auto changed=navcore::route(g,"A","D",o);if(changed.path_nodes[1]!="C")throw std::runtime_error("closure");navcore::RouteMonitor m;navcore::MatchResult hit{g.outgoing("C")[0]};hit.lateral_distance_m=100;for(int i=0;i<2;++i)if(m.update(hit,old)==navcore::RouteState::DEVIATED)throw std::runtime_error("noise");auto st=m.update(hit,old);auto rr=navcore::reroute_if_needed(g,hit,old,"D",st,e);if(!rr.rerouted||rr.new_route.path_nodes.back()!="D")throw std::runtime_error("reroute");std::cout<<"reroute tests passed\n";}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}